// src/extension/session-rooms.ts — the SESSION's mesh rooms, read from the
// pi-mesh identity store. This is the fix for cross-room read pollution:
// the board's default read room must follow the SESSION (the rooms its
// mesh identity declares), not a machine-global config — an agent in room
// Z that calls board_read with no room must never be handed room M's
// entries as if they were its own context.
//
// Source of truth: `<cwd>/.mesh/identity-<sessionId>.json` — the file the
// pi-mesh extension persists per session (rooms survive /reload there).
// STRICT resolution: without a sessionId the session claims NO rooms (no
// union-of-cwd guessing — a mixed-cwd union would silently bless foreign
// rooms for the read gate). A missing or corrupt identity degrades to no
// rooms: reads then need an explicit room, exactly like a session without
// the mesh extension at all.
//
// The identity file is pi-mesh's format, read tolerantly (duck-typed
// fields, best effort): a future format change degrades to "no rooms",
// never to a crash.
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";

/** The rooms this session's mesh identity declares (may be []). */
export function readSessionRooms(cwd: string, sessionId: string | undefined): string[] {
  if (sessionId === undefined || sessionId === "") return [];
  const path = join(cwd, ".mesh", `identity-${sessionId}.json`);
  if (!existsSync(path)) return [];
  let raw: unknown;
  try {
    raw = JSON.parse(readFileSync(path, "utf8"));
  } catch {
    return []; // corrupt identity: degrade, never crash
  }
  if (raw === null || typeof raw !== "object") return [];
  const rooms = (raw as { rooms?: unknown }).rooms;
  if (!Array.isArray(rooms)) return [];
  return rooms.filter((r): r is string => typeof r === "string" && r !== "");
}

// src/extension/runtime.ts — the per-session board runtime: room
// resolution, a store cache (one TypedBoard per room), and the AUTO-JOIN
// peer lifecycle. This is what makes the board NATIVE alongside pi-mesh:
// once `piboard join <room>` has been run (or $PI_BOARD_ROOM is set),
// every session that loads the extension connects a board peer to that
// room automatically — no skill, no manual step.
//
// ROLE MODEL (v0.2 ruling): the auto-join peer is OBSERVER by default —
// a session that never ran a member join gets READ-ONLY presence, never
// write capability. Member presence requires the explicit config written
// by `piboard join` (observer: false). $PI_BOARD_OBSERVER=true can force
// observer even over a member config (the fail-safe direction only).
//
// ANNOUNCE ARCHITECTURE (v0.2 ruling): the extension NEVER announces —
// the watermark-daemon from `piboard join` owns every broadcast (DESIGN
// §5.3 unchanged). The peer exists for presence/role; board_write only
// appends to the store the daemon polls.
//
// NO-SPAWN CONTRACT: the attach probes the broker socket first and, for
// the connect window only, sets MESH_NO_AUTO_BROKER — a board extension
// must never be the reason a broker appears on a machine (the env is
// scoped and restored, never left global: pi-mesh's own extension keeps
// its auto-spawn behavior).
//
// AVAILABILITY CONTRACT: the runtime is built SYNCHRONOUSLY in store-only
// form at session_start — tools answer immediately, reads/greps with an
// explicit room never wait on the peer. The peer attaches in the
// background; if the broker is down the session stays fully usable
// (peerStatus says so honestly), and the next announceable-gated action
// retries the connection (F5 recovery: a DEAD peer — broker restarted —
// is detected, closed, and re-attached once).
import { existsSync } from "node:fs";
import { randomBytes } from "node:crypto";
import { boardDir, BoardStore } from "../store/store.js";
import { readRole } from "../cli/main.js";
import { connectBoardPeer, type BoardPeer } from "../mesh/peer.js";
import { readSessionRooms } from "./session-rooms.js";

export interface BoardRuntime {
  /** The session's PRESENCE room (env > joined config) — the v0.2 chain,
   *  unchanged: the peer/announce role and the write-gate premise. */
  room: string | undefined;
  /** The session's DEFAULT READ room (env > single identity room > config
   *  room). The identity OUTRANKS the config: an agent in room Z on a
   *  machine whose board config says M defaults to Z, never M. */
  readRoom: string | undefined;
  /** Every room this session may call its own (env room + mesh identity
   *  rooms + the machine's config room). The foreign-read gate judges
   *  against this set. */
  rooms: string[];
  /** Read-only membership (observer default — see the module comment). */
  observer: boolean;
  /** The presence peer — null while connecting / failed / none. */
  peer: BoardPeer | null;
  /** Honest one-line status of the auto-join (shown in tool results). */
  peerStatus: string;
  /** The joined alias base (board.json), before room+rand suffixing. */
  aliasBase: string;
  getStore(room?: string): BoardStore;
  /**
   * (Re)attach the peer when needed: no-op when a LIVE peer exists, no
   * room is joined, or the session is observer-only; a DEAD peer (F5:
   * broker restarted mid-session) is closed and re-attached once per
   * call — bounded recovery, never a retry loop.
   */
  ensurePeer(): Promise<void>;
  close(): Promise<void>;
}

/** Room for the session: $PI_BOARD_ROOM > the config saved by `piboard
 *  join`. A corrupt config degrades to no auto-join (honest store-only);
 * explicit tool params override per call (never here). */
export function sessionRoom(env: NodeJS.ProcessEnv = process.env): string | undefined {
  const fromEnv = env.PI_BOARD_ROOM;
  if (fromEnv !== undefined && fromEnv !== "") return fromEnv;
  const read = readRole(env);
  return read.state === "valid" ? read.role.room : undefined;
}

/** The session's DEFAULT READ room: $PI_BOARD_ROOM > exactly-one mesh
 *  identity room > the joined config room > undefined. The identity
 *  outranks the config — an agent in room Z on a machine whose board
 *  config says M defaults to Z, never M (the pollution fix) — but the
 *  config room stays in the chain: the machine's OWN board room is
 *  never foreign to a session that could write there (the write gate
 *  already treats it as "yours"). */
export function sessionReadRoom(
  env: NodeJS.ProcessEnv,
  identityRooms: string[],
  configRoom: string | undefined,
): string | undefined {
  const fromEnv = env.PI_BOARD_ROOM;
  if (fromEnv !== undefined && fromEnv !== "") return fromEnv;
  if (identityRooms.length === 1) return identityRooms[0];
  return configRoom;
}

/** Observer resolution, fail-safe ordered: env-forced observer wins;
 * else the explicit config; else (no config at all) OBSERVER — the
 * v0.2 default. There is no path to member without an explicit
 * member-join config. */
export function sessionObserver(env: NodeJS.ProcessEnv = process.env): boolean {
  if (env.PI_BOARD_OBSERVER === "true") return true;
  const read = readRole(env);
  if (read.state === "valid") return read.role.observer;
  return true;
}

/** Per-session peer alias: the joined alias + the ROOM + a short random
 * suffix, so the sender name says which board speaks (`board-muse-b636`)
 * and N sessions on one machine never collide on strictAlias. Mesh alias
 * rules forbid brackets — the alias carries the room hyphenated. */
export function sessionPeerAlias(base: string, room: string, suffix: string): string {
  const prefix = `${base}-${room}`.slice(0, 26); // ≤32 total with the -<rand4> suffix
  return `${prefix}-${suffix}`;
}

function randAliasSuffix(): string {
  return randomBytes(2).toString("hex");
}

interface AttachEnv {
  runtimeDir?: string;
}

async function attachPeer(rt: BoardRuntime, env: NodeJS.ProcessEnv, attach: AttachEnv): Promise<void> {
  const room = rt.room;
  if (room === undefined) return;
  // $MESH_RUNTIME_DIR (pi-mesh's own knob) scopes the attach to a test
  // broker; unset = the machine's default runtime dir
  const runtimeDir = attach.runtimeDir ?? (env.MESH_RUNTIME_DIR !== undefined && env.MESH_RUNTIME_DIR !== "" ? env.MESH_RUNTIME_DIR : undefined);
  // no broker listening → store-only, and NEVER spawn one: probe the
  // socket (a mesh broker keeps its local unix socket up even when it
  // also listens on tcp), then keep auto-spawn off for the connect window
  const { brokerSocketPath } = await import("pi-mesh-extension/dist/src/shared/paths.js");
  const sock = brokerSocketPath(runtimeDir, env);
  if (!existsSync(sock)) {
    rt.peerStatus = `no broker at ${sock} — store-only mode (the board never spawns a broker)`;
    return;
  }
  const saved = env.MESH_NO_AUTO_BROKER;
  env.MESH_NO_AUTO_BROKER = "1";
  try {
    const peer = await connectBoardPeer({
      room,
      observer: rt.observer,
      alias: sessionPeerAlias(env.PI_BOARD_ALIAS ?? rt.aliasBase ?? "board", room, randAliasSuffix()),
      noReconnect: true, // bounded: a failed connect must never leave a retrying client behind
      ...(runtimeDir !== undefined ? { runtimeDir } : {}),
    });
    rt.peer = peer;
    rt.peerStatus = `auto-joined ${room} as ${rt.observer ? "observer" : "member"} (presence only — the join daemon announces)`;
  } catch (err) {
    rt.peerStatus = `auto-join failed (${err instanceof Error ? err.message : String(err)}) — store-only mode`;
  } finally {
    if (saved === undefined) delete env.MESH_NO_AUTO_BROKER;
    else env.MESH_NO_AUTO_BROKER = saved;
  }
}

/** Injection surface for tests / hosts: where to read the mesh identity
 *  from. Production derives it from the session_start ctx (see index.ts). */
export interface RuntimeIdentityOpts {
  cwd?: string;
  sessionId?: string;
}

/**
 * Build the runtime SYNCHRONOUSLY in store-only form (cheap, fs-only)
 * and start the background peer attach. Tools are usable the instant
 * this returns — the availability contract.
 */
export function buildBoardRuntime(
  env: NodeJS.ProcessEnv = process.env,
  identity: RuntimeIdentityOpts = {},
): BoardRuntime {
  const room = sessionRoom(env);
  const observer = sessionObserver(env);
  const read = readRole(env);
  const aliasBase = read.state === "valid" ? read.role.alias : "board";
  const identityRooms = readSessionRooms(identity.cwd ?? process.cwd(), identity.sessionId);
  const configRoom = read.state === "valid" ? read.role.room : undefined;
  const rooms = [...new Set([env.PI_BOARD_ROOM ?? "", ...identityRooms, configRoom ?? ""].filter((r) => r !== ""))];
  const readRoom = sessionReadRoom(env, identityRooms, configRoom);

  const stores = new Map<string, BoardStore>();
  let attachBusy = false;
  const rt: BoardRuntime = {
    room,
    readRoom,
    rooms,
    observer,
    aliasBase,
    peer: null,
    peerStatus:
      room === undefined
        ? "no board room joined — store-only mode (pass room explicitly, or run `piboard join <room>`)"
        : "connecting…",
    getStore(explicit?: string): BoardStore {
      const target = explicit ?? room;
      if (target === undefined) throw new Error("no room: pass room explicitly or run `piboard join <room>`");
      let store = stores.get(target);
      if (store === undefined) {
        store = new BoardStore(boardDir(target, env));
        stores.set(target, store);
      }
      return store;
    },
    ensurePeer: async () => {
      if (attachBusy) return;
      if (rt.room === undefined || rt.observer) return; // nothing to ensure for observers
      if (rt.peer !== null) {
        if (rt.peer.client.isOnline()) return;
        // F5: the broker restarted — the peer object is dead weight.
        // Close it and fall through to one re-attach.
        await rt.peer.close().catch(() => {});
        rt.peer = null;
        rt.peerStatus = "peer lost (broker restart?) — re-attaching…";
      }
      attachBusy = true;
      try {
        await attachPeer(rt, env, {});
      } finally {
        attachBusy = false;
      }
    },
    close: async () => {
      if (rt.peer !== null) await rt.peer.close().catch(() => {});
    },
  };
  if (room !== undefined) {
    attachBusy = true; // the background attempt owns the slot until done
    void attachPeer(rt, env, {})
      .catch(() => {})
      .finally(() => {
        attachBusy = false;
      });
  }
  return rt;
}

// src/extension/tools.ts — the board tools (board_write / board_read /
// board_grep / board_watch), ported from the native proposal and adapted
// to the watermark-daemon architecture: board_write NEVER announces —
// the room's join daemon owns every broadcast (DESIGN §5.3); the tool
// appends to the store the daemon polls. Plain JSON Schema parameters
// (zero-dependency), honest statuses (a grep miss is an honest empty),
// and promptGuidelines that teach the high-value behavior: grep before
// retrying, FAIL is the highest-value entry, watch at the turn boundary.
import { checkWriteGate } from "../mesh/gates.js";
import { failSummaryLine, selectNewFails, type NotifiableEntry } from "../mesh/notify.js";
import { ENTRY_TYPES, isEntryType, type Entry, type EntryType } from "../entries/types.js";
import { TypedBoard } from "../entries/board.js";
import type { BoardRuntime } from "./runtime.js";
import type { ExtensionAPI, ToolResult } from "./pi-types.js";
import { textResult } from "./pi-types.js";

export type GetRuntime = () => BoardRuntime | null;

const ROOM_PARAM = {
  type: "string",
  description:
    "Board room; defaults to YOUR session's room ($PI_BOARD_ROOM or your mesh identity). Reading another room's board requires crossRoom: true — foreign context can skew your analysis.",
};

const CROSS_ROOM_PARAM = {
  type: "boolean",
  description: "Deliberately read a board that is not one of your session's rooms. Only set it when the task explicitly names that room.",
};

const ENTRY_TYPE_ENUM = [...ENTRY_TYPES];

const BOARD_WRITE_PARAMETERS = {
  type: "object",
  properties: {
    type: { type: "string", enum: ENTRY_TYPE_ENUM, description: "OBSERVED (seen) | FACT (verified) | FAIL (falsified path) | CLAIM (informational ownership) | PATCH_SUMMARY (what a landed change did)" },
    text: { type: "string", description: "Summary line — must survive a turn boundary by being cheap to read." },
    detail: { type: "string", description: "Optional long form — unfolded only by board_read { id }." },
    ref: { type: "string", description: "Optional git-reachable anchor (path, commit, URL)." },
    leaseRef: { type: "string", description: "Optional mesh_claim lease id — annotation only; enforcement never lives here." },
    room: ROOM_PARAM,
  },
  required: ["type", "text"],
} as const;

const BOARD_READ_PARAMETERS = {
  type: "object",
  properties: {
    id: { type: "string", description: "Unfold this entry's detail (the only path detail takes to a reader)." },
    limit: { type: "number", description: "Window size (newest first), capped." },
    room: ROOM_PARAM,
    crossRoom: CROSS_ROOM_PARAM,
  },
} as const;

const BOARD_GREP_PARAMETERS = {
  type: "object",
  properties: {
    query: { type: "string", description: "Boolean search: ',' = OR, '&' = AND (AND binds tighter), case-insensitive; matches text AND detail." },
    type: { type: "string", enum: ENTRY_TYPE_ENUM, description: "Filter by entry type." },
    limit: { type: "number", description: "Max rows." },
    room: ROOM_PARAM,
    crossRoom: CROSS_ROOM_PARAM,
  },
  required: ["query"],
} as const;

const BOARD_WATCH_PARAMETERS = {
  type: "object",
  properties: { room: ROOM_PARAM, crossRoom: CROSS_ROOM_PARAM },
} as const;

function badParams(message: string): ToolResult {
  return textResult(`usage: ${message}`);
}

function boardFor(runtime: BoardRuntime, room: unknown): TypedBoard {
  const target = typeof room === "string" && room !== "" ? room : undefined;
  return new TypedBoard(runtime.getStore(target));
}

/** Resolve the READ target room: explicit param > the session's readRoom
 *  (identity/env — never the machine config). Enforces the foreign-read
 *  gate: a session that HAS rooms cannot silently read another room's
 *  board — that needs crossRoom:true (deliberate, banner-marked). A
 *  session with NO rooms keeps the v0.2 store-only freedom: any explicit
 *  room, no banner (nothing to judge foreignness against). */
function resolveReadTarget(
  runtime: BoardRuntime,
  roomParam: unknown,
  crossRoom: unknown,
): { ok: true; room: string; foreign: boolean } | { ok: false; error: string } {
  const explicit = typeof roomParam === "string" && roomParam !== "" ? roomParam : undefined;
  const deliberate = crossRoom === true;
  if (explicit === undefined) {
    if (runtime.readRoom === undefined) {
      const hint =
        runtime.rooms.length > 1
          ? `you are in rooms [${runtime.rooms.join(", ")}] — pass room explicitly`
          : "no default room for this session — pass room explicitly";
      return { ok: false, error: `board needs a room: ${hint}` };
    }
    return { ok: true, room: runtime.readRoom, foreign: false };
  }
  const foreign = runtime.rooms.length > 0 && !runtime.rooms.includes(explicit);
  if (foreign && !deliberate) {
    return {
      ok: false,
      error:
        `not_your_room: "${explicit}" is not one of this session's rooms [${runtime.rooms.join(", ")}] — ` +
        `foreign board context can skew your analysis; pass crossRoom: true only if the task explicitly names this room`,
    };
  }
  return { ok: true, room: explicit, foreign };
}

/** First line of a deliberately-foreign read — the reader must SEE that
 *  the context is not from its own room before absorbing it. */
function foreignBanner(room: string): string {
  return `⚠ foreign board [${room}] — context may not apply to your work`;
}

function entryLine(entry: Entry): string {
  return `${entry.id} ${entry.type} ${entry.at} ${entry.author}: ${entry.text}`;
}

// ---- board_write ----

function execBoardWrite(getRuntime: GetRuntime, params: Record<string, unknown>): ToolResult {
  const runtime = getRuntime();
  if (runtime === null) return textResult("board: session runtime not ready — retry");
  const roomParam = params.room;
  const room = typeof roomParam === "string" && roomParam !== "" ? roomParam : runtime.room;
  if (room === undefined) {
    return badParams("board_write needs a room (pass room, set $PI_BOARD_ROOM, or run `piboard join <room>`)");
  }

  const type = params.type;
  if (typeof type !== "string" || !isEntryType(type)) {
    return badParams(`board_write type must be one of ${ENTRY_TYPES.join(" | ")}`);
  }
  const text = params.text;
  if (typeof text !== "string" || text.trim() === "") return badParams("board_write needs a non-empty text");

  // the write gate runs BEFORE the kernel (DESIGN §5.2) — the session's
  // auto-joined role decides; an observer session writes nothing
  const gate = checkWriteGate({ observer: runtime.observer, room });
  if (!gate.ok) return textResult(`${gate.reason} — ${gate.detail}`);

  const board = boardFor(runtime, room);
  let entry: Entry;
  try {
    entry = board.write({
      type,
      room,
      text,
      ...(typeof params.detail === "string" && params.detail !== "" ? { detail: params.detail } : {}),
      ...(typeof params.ref === "string" && params.ref !== "" ? { ref: params.ref } : {}),
      ...(typeof params.leaseRef === "string" && params.leaseRef !== "" ? { leaseRef: params.leaseRef } : {}),
      author: runtime.aliasBase,
    });
  } catch (err) {
    return textResult(`error: ${err instanceof Error ? err.message : String(err)}`);
  }
  // writer-announces is deliberately NOT here (v0.2 ruling): the room's
  // join daemon owns every broadcast — this write is announced when the
  // daemon's watermark poll sees it, exactly like a CLI write.
  return textResult(`${entryLine(entry)}\npersisted — the room's board presence (piboard join) announces it`);
}

// ---- board_read ----

function execBoardRead(getRuntime: GetRuntime, params: Record<string, unknown>): ToolResult {
  const runtime = getRuntime();
  if (runtime === null) return textResult("board: session runtime not ready — retry");
  const target = resolveReadTarget(runtime, params.room, params.crossRoom);
  if (!target.ok) return badParams(target.error);
  const board = boardFor(runtime, target.room);

  const id = params.id;
  if (typeof id === "string" && id !== "") {
    const entry = board.readById(id);
    if (entry === undefined) return textResult(`not_found: no such entry ${id}`);
    const lines = [`${entry.id} ${entry.type} ${entry.author} ${entry.at}`, entry.text];
    if (typeof entry.detail === "string") lines.push("--- detail ---", entry.detail);
    if (typeof entry.ref === "string") lines.push(`ref: ${entry.ref}`);
    if (typeof entry.leaseRef === "string") lines.push(`lease: ${entry.leaseRef}`);
    return textResult((target.foreign ? [foreignBanner(target.room)] : []).concat(lines).join("\n"));
  }

  let limit = board.store.limits.readWindowDefault;
  if (typeof params.limit === "number" && Number.isInteger(params.limit) && params.limit > 0) {
    limit = Math.min(params.limit, board.store.limits.readWindowMax);
  }
  const entries = board.read(limit);
  if (entries.length === 0) return textResult("(board is empty for this room)");
  const lines = entries.map(entryLine);
  return textResult((target.foreign ? [foreignBanner(target.room)] : []).concat(lines).join("\n"));
}

// ---- board_grep ----

function execBoardGrep(getRuntime: GetRuntime, params: Record<string, unknown>): ToolResult {
  const runtime = getRuntime();
  if (runtime === null) return textResult("board: session runtime not ready — retry");
  const query = params.query;
  if (typeof query !== "string" || query === "") return badParams("board_grep needs a query (',' = OR, '&' = AND)");
  const typeParam = params.type;
  if (typeParam !== undefined && (typeof typeParam !== "string" || !isEntryType(typeParam))) {
    return badParams(`board_grep type must be one of ${ENTRY_TYPES.join(" | ")}`);
  }
  const target = resolveReadTarget(runtime, params.room, params.crossRoom);
  if (!target.ok) return badParams(target.error);
  const board = boardFor(runtime, target.room);
  try {
    const rows = board.grep(query, {
      ...(typeParam !== undefined ? { type: typeParam as EntryType } : {}),
      ...(typeof params.limit === "number" && Number.isInteger(params.limit) && params.limit > 0 ? { limit: params.limit } : {}),
    });
    // a miss is an honest empty — never an error, never invented rows;
    // a (in detail) marker points at the long form for board_read { id }
    const lines = rows.map((r) => `${r.entry.id} ${r.entry.type}: ${r.entry.text}${r.matchedInDetail ? " (in detail)" : ""}`);
    return textResult(
      (target.foreign ? [foreignBanner(target.room)] : [])
        .concat(rows.length === 0 ? ["(no match)"] : lines)
        .join("\n"),
    );
  } catch (err) {
    return textResult(`error: ${err instanceof Error ? err.message : String(err)}`);
  }
}

// ---- board_watch ----

function execBoardWatch(getRuntime: GetRuntime, params: Record<string, unknown>): ToolResult {
  const runtime = getRuntime();
  if (runtime === null) return textResult("board: session runtime not ready — retry");
  const target = resolveReadTarget(runtime, params.room, params.crossRoom);
  if (!target.ok) return badParams(target.error);
  const board = boardFor(runtime, target.room);
  const notifiable: NotifiableEntry[] = board.read(board.store.limits.readWindowMax).map((e) => ({
    id: e.id,
    type: e.type,
    room: e.room,
    short: e.text,
    at: e.at,
  }));
  // TOOL variant: newest-first — when the clip cuts, what falls off is
  // the OLDEST failure, not the fresh one a turn needs first (the CLI
  // boundary variant keeps selectNewFails' oldest-first contract).
  const line = failSummaryLine(selectNewFails(notifiable, 0).reverse());
  if (line === "") return textResult("(no FAIL entries recorded)");
  return textResult((target.foreign ? [foreignBanner(target.room)] : []).concat([line]).join("\n"));
}

// ---- registration ----

export function registerTools(pi: ExtensionAPI, getRuntime: GetRuntime): void {
  pi.registerTool({
    name: "board_write",
    label: "Board Write",
    description:
      "Append a typed entry to the shared context board (OBSERVED | FACT | FAIL | CLAIM | PATCH_SUMMARY). " +
      "The board is the room's durable, searchable team memory — entries outlive messages.",
    promptSnippet: "Record a finding/failure/claim on the shared board.",
    promptGuidelines:
      "FAIL is the highest-value entry: record every falsified approach immediately so peers stop re-burning " +
      "budget on it. Keep text one skimmable line; put the long story in detail (read via board_read { id }). " +
      "Pair a CLAIM with the mesh_claim lease id in leaseRef — the board informs, the lease enforces. " +
      "Writes announce through the room's board presence (piboard join), not this session.",
    parameters: BOARD_WRITE_PARAMETERS,
    execute: (_toolCallId, params) => execBoardWrite(getRuntime, params),
  });

  pi.registerTool({
    name: "board_read",
    label: "Board Read",
    description:
      "Read the board's recent window (newest first, one-line summaries), or unfold one entry's detail by id.",
    promptSnippet: "Read recent board entries, or unfold one entry.",
    promptGuidelines:
      "First action when picking up shared work: read the window to absorb what the room already knows. " +
      "Use { id } to unfold detail — it is the only path the long form takes. " +
      "NEVER import another room's board into your reasoning unless the task explicitly names that room " +
      "(crossRoom: true) — foreign context can skew your analysis.",
    parameters: BOARD_READ_PARAMETERS,
    execute: (_toolCallId, params) => execBoardRead(getRuntime, params),
  });

  pi.registerTool({
    name: "board_grep",
    label: "Board Grep",
    description:
      "Search the board's FULL recorded history (rotated segments included): ',' = OR, '&' = AND " +
      "(AND binds tighter), case-insensitive, over text and detail. A miss returns an honest empty.",
    promptSnippet: "Search board history before retrying an approach.",
    promptGuidelines:
      "BEFORE retrying an approach or asking a peer, grep the board — a FAIL hit saves the whole budget of " +
      "that dead end. A detail match deserves a follow-up board_read { id }. " +
      "Grep YOUR room's board; a foreign room needs crossRoom:true and an explicit task reason.",
    parameters: BOARD_GREP_PARAMETERS,
    execute: (_toolCallId, params) => execBoardGrep(getRuntime, params),
  });

  pi.registerTool({
    name: "board_watch",
    label: "Board Watch",
    description:
      "The FAIL digest: every FAIL entry visible on the board, one skimmable line — the turn-boundary " +
      "summary (normal priority, never an urgent frame).",
    promptSnippet: "Skim the room's recorded failures.",
    promptGuidelines: "Call at the start of a turn alongside mesh checks to see what the room already falsified.",
    parameters: BOARD_WATCH_PARAMETERS,
    execute: (_toolCallId, params) => execBoardWatch(getRuntime, params),
  });
}

// src/extension/index.ts — Pi extension entrypoint (the `"pi"` manifest
// points here via the root extension.ts). Thin adapter, mirror of the
// pi-mesh extension lifecycle: tools register IMMEDIATELY (they answer
// in store-only mode when nothing is joined); session_start builds the
// runtime and AUTO-JOINS the board room when one is resolvable —
// observer by default (v0.2 ruling), member only via an explicit
// `piboard join`. session_shutdown closes the peer.
import type { ExtensionAPI } from "./pi-types.js";
import { registerTools, type GetRuntime } from "./tools.js";
import { buildBoardRuntime, type BoardRuntime } from "./runtime.js";

/** Optional injection for tests / hosts with a pre-built runtime.
 *  Production (the pi manifest) calls the default export with no options. */
export interface BoardExtensionOptions {
  runtime?: (env: NodeJS.ProcessEnv) => BoardRuntime;
}

export default function boardExtension(pi: ExtensionAPI, opts: BoardExtensionOptions = {}): void {
  let runtime: BoardRuntime | null = null;
  const getRuntime: GetRuntime = () => runtime;

  // Tools answer `store-only` before session_start — never blocked.
  registerTools(pi, getRuntime);

  pi.on("session_start", (_event, ctx) => {
    // SYNCHRONOUS store-only build: tools are usable the instant this
    // fires — reads/greps never wait on the peer (availability contract,
    // runtime.ts). The peer attaches in the background; a down broker
    // never blocks session start. The ctx carries the session identity
    // (sessionId/cwd) used for session-scoped room resolution.
    try {
      runtime = (opts.runtime ?? ((env: NodeJS.ProcessEnv) => buildBoardRuntime(env, { cwd: ctx?.cwd, sessionId: ctx?.sessionId })))(
        process.env,
      );
    } catch {
      runtime = null; // honest degraded mode: tools with explicit rooms still work
    }
  });

  pi.on("session_shutdown", () => {
    const current = runtime;
    runtime = null;
    void current?.close().catch(() => {});
  });
}

// src/extension/pi-types.ts — the local Pi ExtensionAPI mirror (the
// pi-mesh pattern): the extension layer must not import the host package,
// so the tiny surface it needs is mirrored here. Kept in lockstep with
// pi-mesh-extension's src/extension/pi-types.ts shape.
export interface ToolTextContent {
  type: "text";
  text: string;
}

export interface ToolResult {
  content: ToolTextContent[];
  details?: Record<string, unknown>;
}

export interface ToolDefinition {
  name: string;
  label?: string;
  description?: string;
  promptSnippet?: string;
  promptGuidelines?: string;
  parameters?: Record<string, unknown>;
  execute: (
    toolCallId: string,
    params: Record<string, unknown>,
    signal: AbortSignal | undefined,
    onUpdate: ((update: unknown) => void) | undefined,
    ctx: unknown,
  ) => Promise<ToolResult> | ToolResult;
}

/** What the host passes at session_start (duck-typed, tolerant: the
 *  fields we need, nothing more — the pi-mesh extension relies on the
 *  same host contract for its identity persistence). */
export interface SessionStartCtx {
  sessionId?: string;
  cwd?: string;
}

export interface ExtensionAPI {
  registerTool(def: ToolDefinition): void;
  on(event: "session_start", fn: (event: unknown, ctx?: SessionStartCtx) => void): void;
  on(event: "session_shutdown", fn: () => void): void;
}

export function textResult(text: string, details?: Record<string, unknown>): ToolResult {
  const out: ToolResult = { content: [{ type: "text", text }] };
  if (details !== undefined) out.details = details;
  return out;
}

// test/session-rooms.test.ts — session-scoped read rooms + the
// foreign-read gate (the cross-room pollution fix). A session's mesh
// identity (`.mesh/identity-<sessionId>.json`, cwd-relative) is the
// source of truth for what "its" rooms are; the machine config no longer
// decides the DEFAULT read of a session that has rooms of its own.
import assert from "node:assert/strict";
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { describe, it } from "node:test";
import boardExtension from "../src/extension/index.js";
import type { ExtensionAPI, SessionStartCtx, ToolDefinition } from "../src/extension/pi-types.js";
import { buildBoardRuntime, type BoardRuntime } from "../src/extension/runtime.js";
import { TypedBoard } from "../src/entries/board.js";
import { BoardStore } from "../src/store/store.js";

/** hermetic env: tmp state root, no inherited PI_BOARD_* / MESH_* */
const ENV_KEYS = ["PI_BOARD_STATE_DIR", "PI_BOARD_ROOM", "PI_BOARD_OBSERVER", "PI_BOARD_ALIAS", "MESH_RUNTIME_DIR", "MESH_NO_AUTO_BROKER"];

interface Guard {
  env: NodeJS.ProcessEnv;
  set(key: string, value: string | undefined): void;
  restore(): void;
}

function envGuard(): Guard {
  const saved = new Map<string, string | undefined>();
  for (const key of ENV_KEYS) saved.set(key, process.env[key]);
  const env: NodeJS.ProcessEnv = { ...process.env };
  for (const key of ENV_KEYS) delete env[key];
  return {
    env,
    set: (key, value) => {
      if (value === undefined) delete env[key];
      else env[key] = value;
    },
    restore: () => {
      for (const [key, value] of saved) {
        if (value === undefined) delete process.env[key];
        else process.env[key] = value;
      }
    },
  };
}

interface Ctx {
  guard: Guard;
  root: string; // state root + cwd for the identity
  sessionId: string;
  /** write the session's mesh identity file with these rooms */
  identity(rooms: string[]): void;
  /** write the machine board.json role config */
  config(room: string, observer: boolean): void;
  runtime(): BoardRuntime;
  tools(rt: BoardRuntime): Map<string, ToolDefinition>;
  cleanup(): void;
}

function withCtx(fn: (ctx: Ctx) => void | Promise<void>): () => Promise<void> {
  return async () => {
    const guard = envGuard();
    const root = mkdtempSync(path.join(tmpdir(), "pi-board-srooms-"));
    const sessionId = "01234567-89ab-4cde-8f01-234567890abc";
    guard.set("PI_BOARD_STATE_DIR", path.join(root, "state"));
    guard.set("MESH_RUNTIME_DIR", path.join(root, "no-broker")); // probe fails → no attach, no sockets
    const ctx: Ctx = {
      guard,
      root,
      sessionId,
      identity(rooms: string[]) {
        mkdirSync(path.join(root, ".mesh"), { recursive: true });
        writeFileSync(
          path.join(root, ".mesh", `identity-${sessionId}.json`),
          JSON.stringify({ version: 1, sessionId, alias: "agent-test", rooms }),
        );
      },
      config(room: string, observer: boolean) {
        mkdirSync(path.join(root, "state"), { recursive: true });
        writeFileSync(path.join(root, "state", "board.json"), JSON.stringify({ room, alias: "board-test", observer, watermarkMs: 0 }));
      },
      runtime: () => buildBoardRuntime(guard.env, { cwd: root, sessionId }),
      tools: (rt: BoardRuntime) => {
        const tools = new Map<string, ToolDefinition>();
        const handlers = new Map<string, (event: unknown, ctx?: SessionStartCtx) => void>();
        const pi = {
          registerTool: (def: ToolDefinition) => tools.set(def.name, def),
          on: (event: string, fn: (event: unknown, ctx?: SessionStartCtx) => void) => handlers.set(event, fn),
        } as unknown as ExtensionAPI;
        boardExtension(pi, { runtime: () => rt });
        handlers.get("session_start")?.({}, { sessionId, cwd: root });
        return tools;
      },
      cleanup: () => rmSync(root, { recursive: true, force: true }),
    };
    try {
      await fn(ctx);
    } finally {
      guard.restore();
      ctx.cleanup();
    }
  };
}

/** seed an entry into a room's store directly (no gate involved) */
function seed(ctx: Ctx, room: string, text: string): void {
  const store = new BoardStore(path.join(ctx.guard.env.PI_BOARD_STATE_DIR!, room));
  new TypedBoard(store).write({ type: "FACT", room, text, author: "seeder" });
}

async function run(tool: ToolDefinition | undefined, params: Record<string, unknown>): Promise<string> {
  assert.ok(tool !== undefined, "tool registered");
  const res = await tool!.execute("c", params, undefined, undefined, undefined);
  return res.content[0]?.text ?? "";
}

describe("session-scoped read rooms (the pollution fix)", () => {
  it("identity room OUTRANKS the machine config: agent in zoma on a muse-configured machine defaults to zoma", withCtx(async (ctx) => {
    ctx.identity(["zoma"]);
    ctx.config("muse", false); // the old pollution vector: machine board = muse
    seed(ctx, "muse", "muse entry that must NOT be the default context");
    seed(ctx, "zoma", "zoma entry the agent works on");
    const tools = ctx.tools(ctx.runtime());
    const read = await run(tools.get("board_read"), {});
    assert.match(read, /zoma entry the agent works on/);
    assert.ok(!read.includes("muse entry"), "the muse board leaked into the default read");
  }));

  it("foreign room: refused without crossRoom, banner-marked with it", withCtx(async (ctx) => {
    ctx.identity(["zoma"]);
    seed(ctx, "muse", "muse fact");
    const tools = ctx.tools(ctx.runtime());
    const refused = await run(tools.get("board_read"), { room: "muse" });
    assert.match(refused, /not_your_room/);
    assert.match(refused, /crossRoom: true/);
    const allowed = await run(tools.get("board_read"), { room: "muse", crossRoom: true });
    assert.match(allowed, /⚠ foreign board \[muse\]/);
    assert.match(allowed, /muse fact/);
    // grep and watch share the gate (grep needs the explicit foreign room —
    // without it, it searches the session's own default room)
    const grepRefused = await run(tools.get("board_grep"), { query: "muse", room: "muse" });
    assert.match(grepRefused, /not_your_room/);
    const watchRefused = await run(tools.get("board_watch"), { room: "muse" });
    assert.match(watchRefused, /not_your_room/);
  }));

  it("the machine's OWN config room is never foreign (coherent with the write gate)", withCtx(async (ctx) => {
    ctx.config("muse", false);
    seed(ctx, "muse", "machine board entry");
    const tools = ctx.tools(ctx.runtime());
    const read = await run(tools.get("board_read"), {}); // no identity → config default
    assert.match(read, /machine board entry/);
    const explicit = await run(tools.get("board_read"), { room: "muse" }); // and never flagged foreign
    assert.ok(!explicit.includes("foreign"));
  }));

  it("no identity, no env, no config: explicit room stays free (the v0.2 store-only feature), no banner", withCtx(async (ctx) => {
    seed(ctx, "anyroom", "store-only entry");
    const rt = ctx.runtime();
    assert.equal(rt.readRoom, undefined);
    const tools = ctx.tools(rt);
    const needRoom = await run(tools.get("board_read"), {});
    assert.match(needRoom, /pass room explicitly/);
    const explicit = await run(tools.get("board_read"), { room: "anyroom" });
    assert.match(explicit, /store-only entry/);
    assert.ok(!explicit.includes("foreign")); // nothing to judge foreignness against
  }));

  it("multi-room identity: no silent default — the error names the rooms", withCtx(async (ctx) => {
    ctx.identity(["zoma", "rizob"]);
    const tools = ctx.tools(ctx.runtime());
    const read = await run(tools.get("board_read"), {});
    assert.match(read, /rooms \[zoma, rizob\]/);
    assert.match(read, /pass room explicitly/);
    // an explicit pick among OWN rooms is not foreign
    const pick = await run(tools.get("board_read"), { room: "rizob" });
    assert.ok(!pick.includes("not_your_room"));
  }));

  it("env room counts as the session's own (operator pin)", withCtx(async (ctx) => {
    ctx.identity(["zoma"]);
    ctx.guard.set("PI_BOARD_ROOM", "default");
    seed(ctx, "default", "env-pinned entry");
    const tools = ctx.tools(ctx.runtime());
    const read = await run(tools.get("board_read"), {});
    assert.match(read, /env-pinned entry/); // env wins over identity
  }));

  it("corrupt identity degrades to no rooms (never a crash), config still applies", withCtx(async (ctx) => {
    mkdirSync(path.join(ctx.root, ".mesh"), { recursive: true });
    writeFileSync(path.join(ctx.root, ".mesh", `identity-${ctx.sessionId}.json`), "NOT JSON");
    ctx.config("muse", false);
    seed(ctx, "muse", "degraded but working");
    const rt = ctx.runtime();
    assert.deepEqual(rt.rooms, ["muse"]);
    const tools = ctx.tools(rt);
    const read = await run(tools.get("board_read"), {});
    assert.match(read, /degraded but working/);
  }));
});

// test/extension.test.ts — task_0001: the ported native extension —
// auto-join (observer default), no-spawn, F5 recovery, store-only tools.
// Real broker where a peer attaches; hermetic env per test.
import assert from "node:assert/strict";
import { mkdirSync, mkdtempSync, rmSync, writeFileSync, existsSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { describe, it } from "node:test";
import type { ExtensionAPI, ToolDefinition } from "../src/extension/pi-types.js";
import boardExtension from "../src/extension/index.js";
import {
  buildBoardRuntime,
  sessionObserver,
  sessionPeerAlias,
  sessionRoom,
  type BoardRuntime,
} from "../src/extension/runtime.js";

const ROOM = "ext";
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

interface Ctx {
  root: string;
  runDir: string;
  stateDir: string;
  env: NodeJS.ProcessEnv;
  broker: { close(): Promise<void>; socketPath: string } | null;
  mates: { close(): Promise<void> }[];
  cleanup(): Promise<void>;
}

async function withCtx(setup: (c: Ctx) => Promise<void> = async () => {}): Promise<Ctx> {
  const root = mkdtempSync(path.join(tmpdir(), "pi-board-ext-"));
  const runDir = path.join(root, "run");
  const stateDir = path.join(root, "state");
  mkdirSync(runDir, { recursive: true });
  mkdirSync(stateDir, { recursive: true });
  const ctx: Ctx = {
    root,
    runDir,
    stateDir,
    env: { PI_BOARD_STATE_DIR: stateDir, MESH_RUNTIME_DIR: runDir },
    broker: null,
    mates: [],
    async cleanup() {
      for (const m of this.mates) await m.close().catch(() => {});
      await this.broker?.close().catch(() => {});
      rmSync(root, { recursive: true, force: true });
    },
  };
  await setup(ctx);
  return ctx;
}

async function spawnBroker(ctx: Ctx): Promise<void> {
  const brokerMod = await import("pi-mesh-extension/dist/src/broker/broker.js");
  const { DEFAULT_CONFIG } = await import("pi-mesh-extension/dist/src/shared/config.js");
  const { DEFAULT_POLICY } = await import("pi-mesh-extension/dist/src/broker/policy.js");
  ctx.broker = await brokerMod.createBroker({
    socketPath: path.join(ctx.runDir, "broker.sock"),
    config: DEFAULT_CONFIG,
    policy: DEFAULT_POLICY,
    stateDir: path.join(ctx.root, "broker-state"),
  });
}

async function addMate(ctx: Ctx, alias: string): Promise<void> {
  const { MeshClient } = await import("pi-mesh-extension/dist/src/client/client.js");
  const mate = new MeshClient({ alias, rooms: [ROOM], runtimeDir: ctx.runDir, config: {}, noReconnect: true });
  await mate.connect();
  ctx.mates.push(mate);
}

/** Wait for the background attach to settle past "connecting…". */
async function settle(rt: BoardRuntime, timeoutMs = 5_000): Promise<string> {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    if (!rt.peerStatus.startsWith("connecting")) return rt.peerStatus;
    await sleep(50);
  }
  return rt.peerStatus;
}

function toolsOf(rt: BoardRuntime | null): Map<string, ToolDefinition> {
  const tools = new Map<string, ToolDefinition>();
  const handlers = new Map<string, () => void>();
  const pi = {
    registerTool: (def: ToolDefinition) => tools.set(def.name, def),
    on: (event: string, fn: () => void) => {
      handlers.set(event, fn);
    },
  } as unknown as ExtensionAPI;
  boardExtension(pi, rt !== null ? { runtime: () => rt } : {});
  // Fire session_start ONLY for an injected runtime. With rt === null the
  // handler would build a REAL runtime from process.env — on a machine with
  // a joined board config that attaches a live peer to the real mesh which
  // nothing closes: a handle leak that hangs the test process (and pollutes
  // the mesh). The null case asserts PRE-START registration — no start.
  if (rt !== null) handlers.get("session_start")?.();
  return tools;
}

function run(tool: ToolDefinition | undefined, params: Record<string, unknown>) {
  assert.ok(tool !== undefined, "tool registered");
  return tool!.execute("c", params, undefined, undefined, undefined) as Promise<{ content: { text: string }[] }>;
}

function textOf(res: { content: { text: string }[] }): string {
  return res.content[0]?.text ?? "";
}

describe("native extension: registration + store-only", () => {
  it("registers the four board tools immediately (before session_start)", () => {
    const tools = toolsOf(null);
    for (const name of ["board_write", "board_read", "board_grep", "board_watch"]) {
      assert.ok(tools.has(name), name);
    }
  });

  it("sessionRoom: env wins over config; corrupt config degrades to no auto-join", async (t) => {
    const ctx = await withCtx();
    t.after(() => ctx.cleanup());
    assert.equal(sessionRoom({ ...ctx.env, PI_BOARD_ROOM: "envroom" }), "envroom");
    assert.equal(sessionRoom(ctx.env), undefined); // absent config
    writeFileSync(path.join(ctx.stateDir, "board.json"), "{broken");
    assert.equal(sessionRoom(ctx.env), undefined); // corrupt degrades honestly
    assert.equal(sessionObserver(ctx.env), true); // and never grants member
  });

  it("sessionObserver: no config → observer (the v0.2 default); member needs the explicit config; env forces observer", async (t) => {
    const ctx = await withCtx();
    t.after(() => ctx.cleanup());
    assert.equal(sessionObserver(ctx.env), true);
    writeFileSync(
      path.join(ctx.stateDir, "board.json"),
      JSON.stringify({ room: ROOM, alias: "board-test", observer: false, watermarkMs: 0 }),
    );
    assert.equal(sessionObserver(ctx.env), false); // explicit member config
    assert.equal(sessionObserver({ ...ctx.env, PI_BOARD_OBSERVER: "true" }), true); // fail-safe override
  });

  it("sessionPeerAlias carries the room, respects the mesh alias bound", () => {
    const alias = sessionPeerAlias("board", "muse", "b636");
    assert.equal(alias, "board-muse-b636");
    assert.ok(alias.length <= 32);
    assert.ok(!alias.includes("["));
    const long = sessionPeerAlias("board", "a-very-long-room-name-here", "zz99");
    assert.ok(long.length <= 32, `got ${long.length}: ${long}`);
  });
});

describe("native extension: auto-join on a real broker", () => {
  it("no config (env room) auto-joins as OBSERVER — broker-side role asserted behaviorally", async (t) => {
    const ctx = await withCtx(async (c) => {
      await spawnBroker(c);
      await addMate(c, "mate");
    });
    t.after(() => ctx.cleanup());
    const rt = buildBoardRuntime({ ...ctx.env, PI_BOARD_ROOM: ROOM });
    t.after(() => rt.close());
    const status = await settle(rt);
    assert.match(status, /auto-joined .* as observer/);
    assert.ok(rt.peer !== null);
    // broker-side truth: the observer peer's own broadcast is refused
    const res = await rt.peer!.client.send({ room: ROOM, broadcast: true, message: "probe" });
    assert.equal(res.status, "blocked");
    assert.equal(res.reason, "observer_readonly");
  });

  it("a member config upgrades the auto-join to member (write capability)", async (t) => {
    const ctx = await withCtx(async (c) => {
      await spawnBroker(c);
      await addMate(c, "mate");
      writeFileSync(
        path.join(c.stateDir, "board.json"),
        JSON.stringify({ room: ROOM, alias: "board-test", observer: false, watermarkMs: 0 }),
      );
    });
    t.after(() => ctx.cleanup());
    const rt = buildBoardRuntime(ctx.env);
    t.after(() => rt.close());
    const status = await settle(rt);
    assert.match(status, /auto-joined .* as member/);
    const res = await rt.peer!.client.send({ room: ROOM, broadcast: true, message: "member probe" });
    assert.equal(res.status, "delivered");
  });

  it("observer sessions cannot board_write (the gate), reads still work", async (t) => {
    const ctx = await withCtx();
    t.after(() => ctx.cleanup());
    const rt = buildBoardRuntime({ ...ctx.env, PI_BOARD_ROOM: ROOM });
    t.after(() => rt.close());
    const tools = toolsOf(rt);
    const denied = await run(tools.get("board_write"), { type: "FAIL", text: "must not land" });
    assert.match(textOf(denied), /observer_readonly/);
    // explicit-room reads never wait on the peer
    const read = await run(tools.get("board_read"), { room: ROOM });
    assert.match(textOf(read), /empty/);
  });

  it("board_write appends (no announce here) and board_read/grep find it — the daemon owns broadcasts", async (t) => {
    const ctx = await withCtx(async (c) => {
      writeFileSync(
        path.join(c.stateDir, "board.json"),
        JSON.stringify({ room: ROOM, alias: "board-test", observer: false, watermarkMs: 0 }),
      );
    });
    t.after(() => ctx.cleanup());
    const rt = buildBoardRuntime(ctx.env);
    t.after(() => rt.close());
    const tools = toolsOf(rt);
    const wrote = await run(tools.get("board_write"), { type: "FAIL", text: "port falsified X" });
    assert.match(textOf(wrote), /port falsified X/);
    assert.match(textOf(wrote), /piboard join.*announces/);
    const read = await run(tools.get("board_read"), {});
    assert.match(textOf(read), /port falsified X/);
    const grep = await run(tools.get("board_grep"), { query: "port&falsified" });
    assert.match(textOf(grep), /port falsified X/);
    const watch = await run(tools.get("board_watch"), {});
    assert.match(textOf(watch), /1 new FAIL/);
  });
});

describe("native extension: no-spawn + F5 recovery", () => {
  it("a broker-less machine NEVER gets a spawned broker — store-only, honestly", async (t) => {
    const ctx = await withCtx(); // no broker spawned
    t.after(() => ctx.cleanup());
    const rt = buildBoardRuntime({ ...ctx.env, PI_BOARD_ROOM: ROOM });
    t.after(() => rt.close());
    const status = await settle(rt);
    assert.match(status, /store-only/);
    assert.equal(existsSync(path.join(ctx.runDir, "broker.sock")), false, "a broker socket appeared!");
  });

  it("session lifecycle: shutdown closes the auto-joined peer (no leaked handles)", async (t) => {
    const ctx = await withCtx(async (c) => {
      await spawnBroker(c);
      await addMate(c, "mate");
    });
    t.after(() => ctx.cleanup());
    // drive the REAL entrypoint lifecycle in production shape (runtime from
    // process.env, scoped to this test's broker). A discarded runtime that
    // leaves a live peer hangs the process — the leak this test guards was
    // real on any machine with a joined board config + live broker.
    const handlers = new Map<string, () => void>();
    const pi = {
      registerTool: () => {},
      on: (event: string, fn: () => void) => handlers.set(event, fn),
    } as unknown as ExtensionAPI;
    const saved: [string, string | undefined][] = [
      ["PI_BOARD_STATE_DIR", process.env.PI_BOARD_STATE_DIR],
      ["MESH_RUNTIME_DIR", process.env.MESH_RUNTIME_DIR],
      ["PI_BOARD_ROOM", process.env.PI_BOARD_ROOM],
    ];
    process.env.PI_BOARD_STATE_DIR = ctx.stateDir;
    process.env.MESH_RUNTIME_DIR = ctx.runDir;
    process.env.PI_BOARD_ROOM = ROOM;
    const mate = ctx.mates[0] as unknown as { status(): Promise<{ peers?: { alias?: string }[] }> };
    const boardPeerPresent = async (): Promise<boolean> => {
      const snap = await mate.status();
      return (snap.peers ?? []).some((p) => (p.alias ?? "").startsWith(`board-${ROOM}`));
    };
    try {
      boardExtension(pi, {});
      handlers.get("session_start")?.();
      const joined = await (async () => {
        const deadline = Date.now() + 5_000;
        while (Date.now() < deadline) {
          if (await boardPeerPresent()) return true;
          await sleep(100);
        }
        return false;
      })();
      assert.ok(joined, "auto-join peer never appeared in the room snapshot");
      handlers.get("session_shutdown")?.();
      const gone = await (async () => {
        const deadline = Date.now() + 5_000;
        while (Date.now() < deadline) {
          if (!(await boardPeerPresent())) return true;
          await sleep(100);
        }
        return false;
      })();
      assert.ok(gone, "shutdown left the auto-joined peer in the room — handle leak");
    } finally {
      for (const [key, value] of saved) {
        if (value === undefined) delete process.env[key];
        else process.env[key] = value;
      }
    }
  });

  it("F5: a dead peer (broker restart) is detected and re-attached by ensurePeer", async (t) => {
    const ctx = await withCtx(async (c) => {
      writeFileSync(
        path.join(c.stateDir, "board.json"),
        JSON.stringify({ room: ROOM, alias: "board-test", observer: false, watermarkMs: 0 }),
      );
    });
    t.after(() => ctx.cleanup());
    // first life: broker up, member attach
    await spawnBroker(ctx);
    await addMate(ctx, "mate");
    const rt = buildBoardRuntime(ctx.env);
    t.after(() => rt.close());
    await settle(rt);
    assert.equal(rt.peer?.client.isOnline(), true);
    // broker dies; the bounded peer goes offline (no reconnect loop)
    await ctx.broker!.close();
    ctx.broker = null;
    await sleep(400);
    assert.equal(rt.peer?.client.isOnline(), false);
    // broker comes back on the same socket; ensurePeer recovers ONCE
    await spawnBroker(ctx);
    await addMate(ctx, "mate2");
    await rt.ensurePeer();
    assert.ok(rt.peer !== null, "peer re-attached");
    assert.equal(rt.peer.client.isOnline(), true);
    const res = await rt.peer.client.send({ room: ROOM, broadcast: true, message: "recovered" });
    assert.equal(res.status, "delivered");
  });
});

// src/mesh/gates.ts — the board's OWN write gate (DESIGN §5.2, task_0006).
//
// This is the second layer of defense in depth; the broker's routeMsg is
// the first. It must therefore hold even when the broker's view is wrong —
// notably during the reconnect window where an observer peer has silently
// re-hello'd as member (the ctl bug class, see peer.ts) — so the decision
// is based on the board's CONFIGURED identity, not on broker state.
//
// Semantics mirror pi-mesh routeMsg's direct/broadcast sender checks, in
// the same order:
//   1. room membership first  → not_member (board word: not_a_member)
//   2. observer role second   → observer_readonly
//   (broker continues with rate limit + policy; those stay broker-side)
// Reads never pass through this gate — it guards write paths only.
import type { BoardPeer } from "./peer.js";

export interface WriteGateInput {
  /** The board's configured membership (peer.observer). */
  observer: boolean;
  /** The board's single room (v0.1). */
  room: string;
  /** Room the write targets; defaults to the board's room. */
  targetRoom?: string;
}

export type WriteGateDecision =
  | { ok: true }
  | { ok: false; status: "blocked"; reason: "observer_readonly" | "not_a_member"; detail: string };

/**
 * Decide a write. Order is load-bearing: membership before observer role,
 * exactly like routeMsg — a peer outside the room is not_a_member even if
 * it would also be read-only, matching which failure the broker reports.
 */
export function checkWriteGate(input: WriteGateInput): WriteGateDecision {
  const target = input.targetRoom ?? input.room;
  if (target !== input.room) {
    return {
      ok: false,
      status: "blocked",
      reason: "not_a_member",
      detail: `board is not a member of "${target}" — it lives in "${input.room}" (single room in v0.1)`,
    };
  }
  if (input.observer) {
    return {
      ok: false,
      status: "blocked",
      reason: "observer_readonly",
      detail: "board joined as observer (--observer): every write path is refused; reads are unaffected",
    };
  }
  return { ok: true };
}

/** Human-readable one-liner for a refused write (CLI/notify wording). */
export function gateRefusalText(decision: Extract<WriteGateDecision, { ok: false }>): string {
  return `blocked: ${decision.reason} — ${decision.detail}`;
}

/**
 * The single enforcement point future write paths (notify, CLI) call: gate
 * first, then the write itself. A refused write never reaches the storage
 * kernel or the broker. Returns the gate decision so callers surface the
 * honest reason verbatim.
 */
export async function guardWrite<T>(
  peer: BoardPeer,
  write: () => Promise<T>,
): Promise<{ ok: true; value: T } | { ok: false; status: "blocked"; reason: string; detail: string }> {
  const decision = checkWriteGate({ observer: peer.observer, room: peer.room });
  if (!decision.ok) return { ok: false, status: "blocked", reason: decision.reason, detail: decision.detail };
  return { ok: true, value: await write() };
}

/**
 * src/store/store.ts — the append-only board kernel: JSONL segments,
 * rotation, caps that refuse (never evict), TTL visibility, and a
 * fail-closed forbidden-key scan.
 *
 * Why segments: a crash mid-write corrupts one segment's tail at worst,
 * never the whole table; rotated segments are immutable and stay
 * greppable. `meta.json` (tmp+rename) holds the id counter — the id is
 * reserved BEFORE the data write, so a crash between the two leaves a gap,
 * never a duplicate.
 */
import { appendFileSync, closeSync, existsSync, mkdirSync, openSync, readFileSync, readdirSync, renameSync, statSync, unlinkSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { FORBIDDEN_KEY_PATTERNS, loadLimits, type Limits } from "../shared/limits.js";

const SEGMENT_GLOB = /^seg-(\d{6})\.jsonl$/;

/** A lock holder older than this is a crashed writer — break its lock. */
const APPEND_LOCK_STALE_MS = 10_000;

/** Anything the board stores: an id, a timestamp, then caller fields. */
export interface StoredEntry {
  id: string;
  at: string;
  [field: string]: unknown;
}

export class BoardFullError extends Error {
  constructor(
    readonly bound: "maxEntries" | "maxTotalBytes",
    message: string,
  ) {
    super(message);
    this.name = "BoardFullError";
  }
}

export class ForbiddenKeyError extends Error {
  constructor(readonly patternIndex: number) {
    // Name the pattern, never the matched text — the error must not echo
    // the secret it refused.
    super(`forbidden_key: entry matches secret pattern #${patternIndex}; refusing to persist`);
    this.name = "ForbiddenKeyError";
  }
}

export interface StoreOptions {
  limits?: Limits;
  /** Clock injection for tests (defaults to Date.now). */
  now?: () => number;
}

/** `<root>/<room>/`; root = `$PI_BOARD_STATE_DIR` or `~/.pi-board`. */
/** State root: `$PI_BOARD_STATE_DIR` or `~/.pi-board` (single source of
 *  truth — the CLI reuses this for board.json instead of duplicating it). */
export function stateRoot(env: NodeJS.ProcessEnv = process.env): string {
  const override = env.PI_BOARD_STATE_DIR;
  return override !== undefined && override !== "" ? override : join(homedir(), ".pi-board");
}

/** `<root>/<room>/` — one directory per room. */
export function boardDir(room: string, env: NodeJS.ProcessEnv = process.env): string {
  return join(stateRoot(env), room);
}

export class BoardStore {
  readonly dir: string;
  readonly limits: Limits;
  private readonly now: () => number;
  private seq: number;

  constructor(dir: string, opts: StoreOptions = {}) {
    this.dir = dir;
    this.limits = opts.limits ?? loadLimits();
    this.now = opts.now ?? Date.now;
    mkdirSync(join(dir, "segments"), { recursive: true, mode: 0o700 });
    this.seq = this.loadMeta().seq;
  }

  // ---- write path ----

  /**
   * Persist one entry. Validation order matters: the forbidden-key scan and
   * field caps run BEFORE any counter reservation or write, so a refused
   * append leaves no trace (no id gap, no partial line).
   */
  append(draft: Record<string, unknown>): StoredEntry {
    this.scanForbiddenKeys(draft);
    // Field caps are BYTE bounds (DESIGN says "8 KiB", not 8192 UTF-16 units).
    const text = draft["text"];
    if (typeof text === "string" && Buffer.byteLength(text, "utf8") > this.limits.maxTextChars) {
      throw new Error(`entry_too_long: text exceeds ${this.limits.maxTextChars} bytes`);
    }
    const detail = draft["detail"];
    if (typeof detail === "string" && Buffer.byteLength(detail, "utf8") > this.limits.maxDetailChars) {
      throw new Error(`entry_too_long: detail exceeds ${this.limits.maxDetailChars} bytes`);
    }
    const draftLine = `${JSON.stringify(draft)}\n`;
    if (Buffer.byteLength(draftLine) > this.limits.segmentMaxBytes) {
      // Fast-fail on the draft line; the authoritative check below measures
      // the FINAL line (id+at add ~40-60 bytes).
      throw new Error(`entry_too_large: single entry exceeds the segment bound (${this.limits.segmentMaxBytes} bytes)`);
    }
    return this.withAppendLock(() => {
      // Cross-process serialization: re-read the counter under the lock so
      // concurrent CLI processes never both write b(N+1).
      this.seq = this.loadMeta().seq;
      const physical = this.physicalStats();
      if (physical.entries + 1 > this.limits.maxEntries) {
        throw new BoardFullError(
          "maxEntries",
          `board_full: ${physical.entries} entries on disk, cap ${this.limits.maxEntries} — append refused (never silently evicted)`,
        );
      }

      // Build the FINAL line, then measure every byte bound against it.
      const entry: StoredEntry = {
        ...draft,
        id: `b${(this.seq + 1).toString(36)}`,
        at: new Date(this.now()).toISOString(),
      };
      const finalLine = `${JSON.stringify(entry)}\n`;
      const finalBytes = Buffer.byteLength(finalLine);
      if (finalBytes > this.limits.segmentMaxBytes) {
        throw new Error(`entry_too_large: single entry exceeds the segment bound (${this.limits.segmentMaxBytes} bytes)`);
      }
      if (physical.bytes + finalBytes > this.limits.maxTotalBytes) {
        throw new BoardFullError(
          "maxTotalBytes",
          `board_full: ${physical.bytes} bytes on disk, cap ${this.limits.maxTotalBytes} — append refused (never silently evicted)`,
        );
      }

      // Persist the reservation BEFORE the data write: a crash between the
      // two leaves a harmless id gap, never a duplicate after reopen. A
      // refusal above simply never persists — the id is reused cleanly.
      this.seq += 1;
      this.saveMeta();
      appendFileSync(this.targetSegmentPath(finalBytes), finalLine, "utf8");
      return entry;
    });
  }

  /**
   * Serialize appends across processes with an O_EXCL lockfile. A crash
   * while holding it leaves a stale file; a holder older than the stale
   * bound is broken (the write either landed or never happened — meta is
   * tmp+rename atomic, so breaking cannot corrupt the table).
   */
  private withAppendLock<T>(fn: () => T): T {
    const lockPath = join(this.dir, "append.lock");
    for (;;) {
      let fd: number | undefined;
      try {
        fd = openSync(lockPath, "wx", 0o600);
      } catch (err) {
        if ((err as NodeJS.ErrnoException).code !== "EEXIST") throw err;
        try {
          if (Date.now() - statSync(lockPath).mtimeMs > APPEND_LOCK_STALE_MS) {
            unlinkSync(lockPath);
          }
        } catch {
          // raced away or unreadable — the retry loop handles both
        }
        Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 5);
        continue;
      }
      try {
        return fn();
      } finally {
        closeSync(fd);
        try {
          unlinkSync(lockPath);
        } catch {
          // best effort
        }
      }
    }
  }

  /**
   * The segment the next line goes to: the current one while it is under
   * both bounds, the NEXT one (rotation) once either is hit. Rotated
   * segments are never reopened for writing — immutability by construction.
   * On rotation, every OLD segment whose newest line is TTL-expired is
   * fully expired (segments are chronological) and pruned physically.
   */
  private targetSegmentPath(incomingBytes: number): string {
    const names = this.segmentNames();
    const lastName = names[names.length - 1];
    if (lastName === undefined) return join(this.dir, "segments", "seg-000001.jsonl");
    const lastPath = join(this.dir, "segments", lastName);
    const entries = this.countLines(lastPath);
    const size = statSync(lastPath).size;
    const rotate = entries >= this.limits.segmentMaxEntries || size + incomingBytes > this.limits.segmentMaxBytes;

    if (rotate) {
      for (const name of names) {
        if (name === lastName) continue;
        const path = join(this.dir, "segments", name);
        let lastAt: string | undefined;
        try {
          const lines = readFileSync(path, "utf8").trimEnd().split("\n");
          lastAt = (JSON.parse(lines[lines.length - 1] ?? "{}") as { at?: string }).at;
        } catch {
          // A torn tail line (crash mid-append) is unparseable: treat the
          // segment as NOT fully expired and move on. Query-side TTL
          // filtering already hides expired entries; pruning must never
          // become a write-path failure that outlives the crash (a parse
          // throw here would refuse every future rotation-triggering append).
          continue;
        }
        if (lastAt !== undefined && this.isExpired(lastAt)) {
          try {
            unlinkSync(path);
          } catch {
            // best effort: an unprunable segment stays invisible to queries
          }
        }
      }
      const next = Number.parseInt(lastName.slice(4, 10), 10) + 1;
      return join(this.dir, "segments", `seg-${String(next).padStart(6, "0")}.jsonl`);
    }
    return lastPath;
  }

  // ---- read path ----

  /** Newest-first window of TTL-visible entries. */
  read(limit = this.limits.readWindowDefault): StoredEntry[] {
    const out: StoredEntry[] = [];
    for (const entry of this.scanVisible()) {
      out.push(entry);
      if (out.length >= limit) break;
    }
    return out;
  }

  byId(id: string): StoredEntry | undefined {
    for (const entry of this.scanVisible()) {
      if (entry.id === id) return entry;
    }
    return undefined;
  }

  /**
   * Case-insensitive substring scan over `text` and `detail`, newest-first.
   * The boolean algebra and output shaping live in the entries layer; this
   * proves the primitive every segment (rotated or not) stays searchable.
   */
  grepSubstr(term: string): Array<{ entry: StoredEntry; inDetail: boolean }> {
    const needle = term.toLowerCase();
    const out: Array<{ entry: StoredEntry; inDetail: boolean }> = [];
    for (const entry of this.scanVisible()) {
      const text = typeof entry.text === "string" ? entry.text : "";
      const detail = typeof entry.detail === "string" ? entry.detail : "";
      if (text.toLowerCase().includes(needle)) out.push({ entry, inDetail: false });
      else if (detail.toLowerCase().includes(needle)) out.push({ entry, inDetail: true });
    }
    return out;
  }

  /** Physical on-disk reality (caps accounting): lines and bytes. */
  physicalStats(): { entries: number; bytes: number } {
    let entries = 0;
    let bytes = 0;
    for (const name of this.segmentNames()) {
      const path = join(this.dir, "segments", name);
      bytes += statSync(path).size;
      entries += this.countLines(path);
    }
    return { entries, bytes };
  }

  // ---- internals ----

  private isExpired(at: string): boolean {
    const t = Date.parse(at);
    return Number.isFinite(t) && t + this.limits.entryTtlMs < this.now();
  }

  /** Newest-first iteration of TTL-visible entries across all segments. */
  private *scanVisible(): Generator<StoredEntry> {
    const names = this.segmentNames(); // ascending
    for (let i = names.length - 1; i >= 0; i -= 1) {
      const raw = readFileSync(join(this.dir, "segments", names[i]!), "utf8");
      const lines = raw.split("\n");
      for (let j = lines.length - 1; j >= 0; j -= 1) {
        const line = lines[j]!.trim();
        if (line === "") continue;
        let entry: StoredEntry;
        try {
          entry = JSON.parse(line) as StoredEntry;
        } catch {
          continue; // a torn tail line from a crash is skipped, never fatal
        }
        if (typeof entry.id !== "string" || typeof entry.at !== "string") continue;
        if (this.isExpired(entry.at)) continue;
        yield entry;
      }
    }
  }

  private segmentNames(): string[] {
    try {
      return readdirSync(join(this.dir, "segments"))
        .filter((name) => SEGMENT_GLOB.test(name))
        .sort();
    } catch {
      return [];
    }
  }

  private countLines(path: string): number {
    const raw = readFileSync(path, "utf8");
    let count = 0;
    for (const line of raw.split("\n")) if (line.trim() !== "") count += 1;
    return count;
  }

  /**
   * Fail-closed forbidden-key scan: every string value in the draft is
   * tested against every pattern. A match refuses; a draft that cannot be
   * scanned or serialized also refuses — the board never persists what it
   * could not prove clean.
   */
  private scanForbiddenKeys(value: unknown, seen = 0): void {
    if (seen > 8) {
      // Fail-closed, literally: a structure too deep to scan is refused,
      // not silently passed (the board never persists what it could not
      // prove clean).
      throw new Error("entry_invalid: nesting deeper than 8 levels cannot be scanned — refusing");
    }
    if (typeof value === "string") {
      for (let i = 0; i < FORBIDDEN_KEY_PATTERNS.length; i += 1) {
        if (FORBIDDEN_KEY_PATTERNS[i]!.test(value)) throw new ForbiddenKeyError(i);
      }
      return;
    }
    if (value === null || typeof value !== "object") return;
    for (const child of Object.values(value as Record<string, unknown>)) {
      this.scanForbiddenKeys(child, seen + 1);
    }
  }

  // ---- meta (id counter) ----

  private metaPath(): string {
    return join(this.dir, "meta.json");
  }

  private loadMeta(): { seq: number } {
    try {
      const raw = JSON.parse(readFileSync(this.metaPath(), "utf8")) as { seq?: unknown };
      if (typeof raw.seq === "number" && Number.isInteger(raw.seq) && raw.seq >= 0) return { seq: raw.seq };
    } catch {
      // absent or corrupt meta: start from the highest id on disk, so ids
      // stay unique even after a crash between reservation and write.
    }
    let seq = 0;
    for (const entry of this.scanAllRawIds()) {
      const n = Number.parseInt(entry.id.slice(1), 36);
      if (Number.isFinite(n) && n > seq) seq = n;
    }
    return { seq };
  }

  private saveMeta(): void {
    const target = this.metaPath();
    const tmp = `${target}.${process.pid}.tmp`;
    writeFileSync(tmp, `${JSON.stringify({ seq: this.seq, version: 1 })}\n`, { encoding: "utf8", mode: 0o600 });
    renameSync(tmp, target);
  }

  /** Physical ids, oldest-first, ignoring TTL (id-reconciliation only). */
  private *scanAllRawIds(): Generator<StoredEntry> {
    for (const name of this.segmentNames()) {
      const raw = readFileSync(join(this.dir, "segments", name), "utf8");
      for (const line of raw.split("\n")) {
        const trimmed = line.trim();
        if (trimmed === "") continue;
        try {
          const entry = JSON.parse(trimmed) as StoredEntry;
          if (typeof entry.id === "string") yield entry;
        } catch {
          // torn tail line: skip
        }
      }
    }
  }
}

/**
 * src/entries/board.ts — the typed surface over the storage kernel:
 * write validation, the read window, id-based detail unfold, and the
 * boolean grep (`,` = OR, `&` = AND, AND binds tighter; case-insensitive
 * over text and detail; a miss is an honest empty list).
 */
import { BoardStore, boardDir, type StoreOptions } from "../store/store.js";
import { validateDraft, type Entry, type EntryDraft, type EntryType } from "./types.js";

/** One grep row: always carries the id; `(in detail)` marks rows whose
 *  match relied on detail (gate review b) — `read --id` is the follow-up. */
export interface GrepRow {
  entry: Entry;
  matchedInDetail: boolean;
}

export class TypedBoard {
  readonly store: BoardStore;

  constructor(store: BoardStore) {
    this.store = store;
  }

  static open(room: string, opts: StoreOptions = {}): TypedBoard {
    return new TypedBoard(new BoardStore(boardDir(room), opts));
  }

  write(draft: Partial<EntryDraft> & Record<string, unknown>): Entry {
    return this.store.append({ ...validateDraft(draft) }) as unknown as Entry;
  }

  /** Newest-first summary window; limit clamped to the configured max. */
  read(limit?: number): Entry[] {
    const wanted = limit === undefined ? this.store.limits.readWindowDefault : limit;
    const clamped = Math.max(1, Math.min(wanted, this.store.limits.readWindowMax));
    return this.store.read(clamped) as unknown as Entry[];
  }

  /** Unfold: the full record including `detail` (constraint #3). */
  readById(id: string): Entry | undefined {
    return this.store.byId(id) as Entry | undefined;
  }

  /**
   * Boolean full-text search. Grammar: `a,b&c` = a OR (b AND c) — AND
   * binds tighter. Terms are case-insensitive substrings over `text` and
   * `detail`. A miss returns []; a row that matched only through detail is
   * marked so a summary line that hides the match never confuses.
   */
  grep(query: string, opts: { limit?: number; type?: EntryType } = {}): GrepRow[] {
    const groups = query
      .split(",")
      .map((group) => group.split("&").map((term) => term.trim().toLowerCase()))
      .filter((terms) => terms.length > 0 && terms.every((term) => term !== ""));
    if (groups.length === 0) {
      throw new Error(`grep_invalid: query has no usable terms: ${JSON.stringify(query)}`);
    }
    const rows: GrepRow[] = [];
    // Full visible span, not the read window: rotated-but-alive segments
    // must stay greppable (DESIGN §2) — the window is a PRESENTATION bound
    // for read, never a search boundary. TTL already bounds the span.
    for (const entry of this.store.read(Number.MAX_SAFE_INTEGER) as unknown as Entry[]) {
      const inText = (term: string): boolean => entry.text.toLowerCase().includes(term);
      const inDetail = (term: string): boolean =>
        entry.detail !== undefined && entry.detail.toLowerCase().includes(term);
      let matchedTextOnly = false;
      let matchedViaDetail = false;
      for (const terms of groups) {
        if (!terms.every((term) => inText(term) || inDetail(term))) continue;
        if (terms.every((term) => inText(term))) matchedTextOnly = true;
        else matchedViaDetail = true;
      }
      if (!matchedTextOnly && !matchedViaDetail) continue;
      if (opts.type !== undefined && entry.type !== opts.type) continue;
      rows.push({ entry, matchedInDetail: !matchedTextOnly && matchedViaDetail });
      if (rows.length >= (opts.limit ?? this.store.limits.grepLimitDefault)) break;
    }
    return rows;
  }
}

/**
 * src/cli/main.ts — the piboard command surface (DESIGN §6): five
 * subcommands, one verb each, honest exit codes.
 *
 * Process model: `join` is the board's PRESENCE — it owns the peer
 * connection and is the only process that announces (a CLI write connecting
 * under the same alias would collide with it; instead the daemon polls the
 * local store and broadcasts entries newer than its persisted watermark).
 * `write`/`read`/`grep` are one-shot local operations; `watch` is a local
 * viewer printing the turn-boundary FAIL summary line.
 *
 * Exit codes: 0 ok · 1 error · 2 usage · 3 not_found (read --id) ·
 * 4 refused (observer / non-member write attempt).
 */
import { closeSync, existsSync, mkdirSync, openSync, readFileSync, readSync, renameSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { boardDir, BoardStore, stateRoot } from "../store/store.js";
import { TypedBoard } from "../entries/board.js";
import { ENTRY_TYPES, isEntryType, validateDraft, type EntryDraft } from "../entries/types.js";
import { loadLimits } from "../shared/limits.js";
import { checkWriteGate, gateRefusalText } from "../mesh/gates.js";
import { announceWrite, failSummaryLine, selectNewFails } from "../mesh/notify.js";
import { connectBoardPeer } from "../mesh/peer.js";
import { parseArgs, specUsage, type ArgSpec, type ParsedArgs } from "./args.js";
import { EXIT_ERROR, EXIT_NOT_FOUND, EXIT_OK, EXIT_REFUSED, EXIT_USAGE } from "./codes.js";

/** Poll pace for the join daemon's announce loop and watch's boundary. */
const ANNOUNCE_POLL_MS = 1_000;
const WATCH_POLL_MS = 500;

interface RoleConfig {
  room: string;
  alias: string;
  observer: boolean;
  /** ISO ms of the newest entry this board presence has announced. */
  watermarkMs: number;
}

function rolePath(env: NodeJS.ProcessEnv = process.env): string {
  return join(stateRoot(env), "board.json");
}

/** The joined-role read, honestly three-stated: a config that EXISTS but
 *  cannot be trusted is NOT "not joined" — reporting it as such would send
 *  the operator to re-join when the real fix is repairing the file. */
export type RoleRead =
  | { state: "absent" }
  | { state: "valid"; role: RoleConfig }
  | { state: "corrupt"; path: string; problem: string };

export function readRole(env: NodeJS.ProcessEnv = process.env): RoleRead {
  const path = rolePath(env);
