  let raw: Partial<RoleConfig>;
  try {
    raw = JSON.parse(readFileSync(path, "utf8")) as Partial<RoleConfig>;
  } catch (err) {
    return { state: "corrupt", path, problem: err instanceof Error ? err.message : "not valid JSON" };
