}

export interface CommandDefinition {
  description: string;
  handler: (args: string, ctx: SessionContext) => void | Promise<void>;
}

export type DeliverAs = "followUp" | "steer" | "nextTurn";

export interface InboundMessage {
  customType: string;
  content: string;
  display: boolean;
  details?: Record<string, unknown>;
}

